save(152,dict(paragraphs=["Urna Bose works across advertising, poetry and literary editing. Her Poet2Poet interviews for Different Truths place sustained conversations with other writers alongside her own creative work. The Nissim award organiser's record identifies her as the second-prize recipient in English poetry for 2021.","What No One Told Me approaches bereavement through the things a household continues to use: rotis, ghee, a tablecloth, washing-up materials and the taste of a familiar meal. The speaker's loss is felt in changed textures and rituals before it can be contained in an explanation. Against ready-made assurances that time will heal, the poem insists on the particular, sensory knowledge of absence."],sources=[source('Setu — Voices Within: Urna Bose','https://www.setumag.com/2022/02/voices-within-urna-bose.html','Advertising, poetry, editing and Different Truths connection.'),source('Different Truths — Urna Bose interviews Vinita Agrawal','https://www.differenttruths.com/a-poet-channels-deep-inner-grief-into-words-and-metaphors/','Dated 4 March 2023; Urna byline and Poet2Poet interview evidence.'),source('Nissim — awards and recognitions','https://www.nissim.in/page/28-awards-and-recognitions','2021 English poetry second prize Urna Bose; first prize Ambika Talwar.')],identity_match='Exact name, advertising career, Different Truths and Poet2Poet match captured biography; organiser corroborates precise award placement.',poems_read=[dict(id=131,title='What No One Told Me',coverage='Complete original English poem',basis='Mother’s absence in rotis/ghee, household objects, food, table and resistance to formulaic consolation.')],limitations=['Broad captured award language refined to organiser’s second-prize result; not the Nissim Ezekiel Poetry Prize.','No solo collection independently verified; interviewed writers’ books not assigned to Urna.','Poem’s bereaved speaker not used as evidence of a private life event.'],search_queries=['"Urna Bose" Nissim 2021','"Urna Bose" Poet2Poet'],next_action='Author/editor review of profile and any future bibliography.'))
